      styles: ["@charset \"UTF-8\";\n\n\n\n\n\n\n.page-hero[_ngcontent-%COMP%] {\n  background: linear-gradient(135deg, var(--dark-primary) 0%, var(--dark-secondary) 100%);\n  padding: 150px 0 80px;\n  color: var(--text-light);\n}\n\n.breadcrumb[_ngcontent-%COMP%] {\n  display: flex;\n  gap: 10px;\n  margin-bottom: 20px;\n  font-size: 14px;\n  color: rgba(255, 255, 255, 0.85);\n}\n.breadcrumb[_ngcontent-%COMP%]   a[_ngcontent-%COMP%] {\n  cursor: pointer;\n  transition: color 0.2s;\n}\n.breadcrumb[_ngcontent-%COMP%]   a[_ngcontent-%COMP%]:hover {\n  color: var(--primary-gold);\n}\n.breadcrumb[_ngcontent-%COMP%]   span[_ngcontent-%COMP%] {\n  color: rgba(255, 255, 255, 0.6);\n}\n\nh1[_ngcontent-%COMP%] {\n  font-size: clamp(2.5rem, 5vw, 4rem);\n  margin-bottom: 20px;\n}\n\n.hero-description[_ngcontent-%COMP%] {\n  font-size: 1.2rem;\n  color: rgba(255, 255, 255, 0.95);\n  max-width: 700px;\n}\n\n\n\n\n\n.services-features-section[_ngcontent-%COMP%] {\n  padding: 100px 0;\n  background: var(--bg-section-light);\n}\n\n.service-intro[_ngcontent-%COMP%] {\n  text-align: center;\n  max-width: 800px;\n  margin: 0 auto 60px;\n}\n.service-intro[_ngcontent-%COMP%]   h2[_ngcontent-%COMP%] {\n  margin-bottom: 20px;\n  color: var(--dark-primary);\n}\n.service-intro[_ngcontent-%COMP%]   p[_ngcontent-%COMP%] {\n  color: #6B7280;\n  font-size: 1.1rem;\n  line-height: 1.8;\n}\n\n.features-grid[_ngcontent-%COMP%] {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 25px;\n  margin-top: 50px;\n}\n\n\n\n.feature-card[_ngcontent-%COMP%] {\n  position: relative;\n  aspect-ratio: 1/1;\n  border-radius: 20px;\n  overflow: hidden;\n  cursor: pointer;\n  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.15);\n  transition: all 0.4s ease;\n}\n.feature-card[_ngcontent-%COMP%]:hover {\n  transform: translateY(-15px) scale(1.02);\n  box-shadow: 0 20px 50px rgba(72, 127, 192, 0.4);\n}\n.feature-card[_ngcontent-%COMP%]:hover   .feature-background[_ngcontent-%COMP%] {\n  transform: scale(1.1