import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { NavbarComponent } from '../../../components/navbar/navbar.component';

interface Vehicle {
  id: string;
  name: string;
  type: string;
  description: string;
  capacity: string;
  features: string[];
  imageAngles: {
    front: string;
    side: string;
    back: string;
    top: string;
  };
}

interface Uniform {
  id: string;
  name: string;
  type: string;
  description: string;
  features: string[];
  idealFor: string[];
  imageAngles: {
    front: string;
    side: string;
    back: string;
    top: string;
  };
}

interface Equipment {
  id: string;
  name: string;
  description: string;
  icon: string;
}

interface SelectedVehicle {
  vehicle: Vehicle;
  quantity: number;
  uniformAssignments: UniformAssignment[];
}

interface UniformAssignment {
  vehicleIndex: number;
  uniformId: string;
}

@Component({
  selector: 'app-proteccion-ejecutiva',
  standalone: true,
  imports: [CommonModule, FormsModule, NavbarComponent],
  templateUrl: './proteccion-ejecutiva.component.html',
  styleUrls: ['./proteccion-ejecutiva.component.scss']
})
export class ProteccionEjecutivaComponent implements OnInit {
  
  vehicles: Vehicle[] = [
    {
      id: 'sedan',
      name: 'Sedán Ejecutivo',
      type: 'Ejecutivo',
      description: 'Vehículo discreto ideal para traslados urbanos de alto nivel',
      capacity: '4 pasajeros',
      features: [
        'Blindaje nivel III-A',
        'Cristales antibalas',
        'Sistema de comunicación encriptada',
        'Neumáticos run-flat',
        'Kit médico avanzado'
      ],
      imageAngles: {
        front: 'assets/vehicles/sedan/0.png',
        side: 'assets/vehicles/sedan/90.png',
        back: 'assets/vehicles/sedan/180.png',
        top: 'assets/vehicles/sedan/270.png'
      }
    },
    {
      id: 'suv',
      name: 'SUV Blindado',
      type: 'Versátil',
      description: 'Vehículo robusto con máxima protección y capacidad',
      capacity: '6 pasajeros',
      features: [
        'Blindaje nivel IV',
        'Cristales antibalas reforzados',
        'Sistema anti-explosivos',
        'Tracción 4x4',
        'Puerto de armas seguro'
      ],
      imageAngles: {
        front: 'assets/vehicles/suv/0.png',
        side: 'assets/vehicles/suv/90.png',
        back: 'assets/vehicles/suv/180.png',
        top: 'assets/vehicles/suv/270.png'
      }
    },
    {
      id: 'todoterreno',
      name: 'Todoterreno Táctico',
      type: 'Terreno Difícil',
      description: 'Vehículo especializado para operaciones en zonas complejas',
      capacity: '5 pasajeros + equipo',
      features: [
        'Blindaje táctico nivel III',
        'Sistema de navegación militar',
        'Winch eléctrico',
        'Suspensión reforzada',
        'Comunicación satelital'
      ],
      imageAngles: {
        front: 'assets/vehicles/todoterreno/0.png',
        side: 'assets/vehicles/todoterreno/90.png',
        back: 'assets/vehicles/todoterreno/180.png',
        top: 'assets/vehicles/todoterreno/270.png'
      }
    },
    {
      id: 'pickup',
      name: 'Pickup Blindada',
      type: 'Carga y Personal',
      description: 'Vehículo de apoyo con capacidad de carga',
      capacity: '3 pasajeros + carga',
      features: [
        'Blindaje nivel III',
        'Plataforma de carga reforzada',
        'Sistema de rastreo GPS',
        'Motor turbo diesel',
        'Capacidad 1.5 toneladas'
      ],
      imageAngles: {
        front: 'assets/vehicles/pickup/0.png',
        side: 'assets/vehicles/pickup/90.png',
        back: 'assets/vehicles/pickup/180.png',
        top: 'assets/vehicles/pickup/270.png'
      }
    },
    {
      id: 'hatchback',
      name: 'Compacto Discreto',
      type: 'Bajo Perfil',
      description: 'Vehículo compacto para operaciones discretas',
      capacity: '4 pasajeros',
      features: [
        'Blindaje nivel II-A',
        'Diseño civil',
        'Alta maniobrabilidad',
        'Bajo consumo',
        'Equipamiento oculto'
      ],
      imageAngles: {
        front: 'assets/vehicles/hatchback/0.png',
        side: 'assets/vehicles/hatchback/90.png',
        back: 'assets/vehicles/hatchback/180.png',
        top: 'assets/vehicles/hatchback/270.png'
      }
    },
    {
      id: 'motocicleta',
      name: 'Motocicleta Táctica',
      type: 'Respuesta Rápida',
      description: 'Unidad de respuesta rápida y reconocimiento',
      capacity: '2 personas',
      features: [
        'Motor 650cc+',
        'Sistema de comunicación',
        'Equipamiento táctico',
        'GPS integrado',
        'Maletas blindadas'
      ],
      imageAngles: {
        front: 'assets/vehicles/motocicleta/0.png',
        side: 'assets/vehicles/motocicleta/90.png',
        back: 'assets/vehicles/motocicleta/180.png',
        top: 'assets/vehicles/motocicleta/270.png'
      }
    },
    {
      id: 'helicoptero',
      name: 'Helicóptero Ejecutivo',
      type: 'Aéreo',
      description: 'Transporte aéreo para traslados rápidos y seguros',
      capacity: '6 pasajeros',
      features: [
        'Piloto certificado',
        'Sistema anti-misiles',
        'Comunicación encriptada',
        'Autonomía 600km',
        'Equipo médico de emergencia'
      ],
      imageAngles: {
        front: 'assets/vehicles/helicoptero/0.png',
        side: 'assets/vehicles/helicoptero/90.png',
        back: 'assets/vehicles/helicoptero/180.png',
        top: 'assets/vehicles/helicoptero/270.png'
      }
    }
  ];

  uniforms: Uniform[] = [
    {
      id: 'camuflaje',
      name: 'Uniforme Táctico Camuflaje',
      type: 'Operaciones Tácticas',
      description: 'Uniforme militar de alto rendimiento para operaciones en campo',
      features: [
        'Tejido ripstop resistente',
        'Patrón de camuflaje multicam',
        'Protección balística integrable',
        'Sistema MOLLE',
        'Resistente al agua y fuego'
      ],
      idealFor: ['Operaciones de campo', 'Zonas rurales', 'Seguridad perimetral'],
      imageAngles: {
        front: 'assets/uniforms/camuflaje/0.png',
        side: 'assets/uniforms/camuflaje/90.png',
        back: 'assets/uniforms/camuflaje/180.png',
        top: 'assets/uniforms/camuflaje/270.png'
      }
    },
    {
      id: 'casual',
      name: 'Vestimenta Civil Táctica',
      type: 'Bajo Perfil',
      description: 'Ropa civil con protección oculta para operaciones discretas',
      features: [
        'Apariencia completamente civil',
        'Chaleco antibalas oculto',
        'Bolsillos tácticos disimulados',
        'Telas de alto rendimiento',
        'Adaptable a cualquier clima'
      ],
      idealFor: ['Protección ejecutiva', 'Eventos públicos', 'Traslados urbanos'],
      imageAngles: {
        front: 'assets/uniforms/casual/0.png',
        side: 'assets/uniforms/casual/90.png',
        back: 'assets/uniforms/casual/180.png',
        top: 'assets/uniforms/casual/270.png'
      }
    },
    {
      id: 'formal',
      name: 'Traje Ejecutivo Blindado',
      type: 'Alto Nivel',
      description: 'Traje formal con protección balística integrada',
      features: [
        'Diseño elegante de sastrería',
        'Protección balística nivel II-A',
        'Tejidos técnicos premium',
        'Corte anatómico',
        'Totalmente personalizable'
      ],
      idealFor: ['Eventos corporativos', 'Reuniones de alto nivel', 'Ceremonias'],
      imageAngles: {
        front: 'assets/uniforms/formal/0.png',
        side: 'assets/uniforms/formal/90.png',
        back: 'assets/uniforms/formal/180.png',
        top: 'assets/uniforms/formal/270.png'
      }
    }
  ];

  equipment: Equipment[] = [
    {
      id: 'k9',
      name: 'Unidad Canina K-9',
      description: 'Perros entrenados para detección y protección',
      icon: '🐕'
    },
    {
      id: 'drones',
      name: 'Drones de Vigilancia',
      description: 'Drones con cámaras térmicas y reconocimiento',
      icon: '🚁'
    },
    {
      id: 'comunicacion',
      name: 'Sistema de Comunicación Avanzado',
      description: 'Radios encriptados y red privada',
      icon: '📡'
    },
    {
      id: 'medico',
      name: 'Kit Médico Táctico',
      description: 'Equipo médico de emergencia avanzado',
      icon: '🏥'
    },
    {
      id: 'contramedidas',
      name: 'Contramedidas Electrónicas',
      description: 'Inhibidores de señal y detección de amenazas',
      icon: '📶'
    },
    {
      id: 'blindaje',
      name: 'Blindaje Personal Adicional',
      description: 'Chalecos y placas balísticas nivel IV',
      icon: '🛡️'
    }
  ];

  selectedVehicles: SelectedVehicle[] = [];
  selectedEquipment: Equipment[] = [];
  
  currentVehicle: Vehicle | null = null;
  currentVehicleAngle: string = 'front';
  
  currentUniform: Uniform | null = null;
  currentUniformAngle: string = 'front';
  
  selectedUniformForVehicle: { vehicleId: string; index: number } | null = null;

  constructor(private router: Router) {}

  ngOnInit(): void {
    // Inicialización si es necesaria
  }

  // MÉTODOS DE VEHÍCULOS
  selectVehicle(vehicle: Vehicle): void {
    this.currentVehicle = vehicle;
    this.currentVehicleAngle = 'front';
  }

  rotateVehicle(direction: 'left' | 'right'): void {
    const angles = ['front', 'side', 'back', 'top'];
    const currentIndex = angles.indexOf(this.currentVehicleAngle);
    
    if (direction === 'right') {
      this.currentVehicleAngle = angles[(currentIndex + 1) % angles.length];
    } else {
      this.currentVehicleAngle = angles[(currentIndex - 1 + angles.length) % angles.length];
    }
  }

  getCurrentVehicleImage(): string {
    if (!this.currentVehicle) return '';
    return this.currentVehicle.imageAngles[this.currentVehicleAngle as keyof typeof this.currentVehicle.imageAngles];
  }

  addVehicle(): void {
    if (!this.currentVehicle) return;

    const existingVehicle = this.selectedVehicles.find(
      sv => sv.vehicle.id === this.currentVehicle!.id
    );

    if (existingVehicle) {
      existingVehicle.quantity++;
      existingVehicle.uniformAssignments.push({
        vehicleIndex: existingVehicle.quantity,
        uniformId: 'casual'
      });
    } else {
      this.selectedVehicles.push({
        vehicle: this.currentVehicle,
        quantity: 1,
        uniformAssignments: [{
          vehicleIndex: 1,
          uniformId: 'casual'
        }]
      });
    }
  }

  removeVehicle(selectedVehicle: SelectedVehicle): void {
    const index = this.selectedVehicles.indexOf(selectedVehicle);
    if (index > -1) {
      this.selectedVehicles.splice(index, 1);
    }
  }

  getTotalVehicles(): number {
    return this.selectedVehicles.reduce((total, sv) => total + sv.quantity, 0);
  }

  // MÉTODOS DE UNIFORMES
  selectUniform(uniform: Uniform): void {
    this.currentUniform = uniform;
    this.currentUniformAngle = 'front';
  }

  rotateUniform(direction: 'left' | 'right'): void {
    const angles = ['front', 'side', 'back', 'top'];
    const currentIndex = angles.indexOf(this.currentUniformAngle);
    
    if (direction === 'right') {
      this.currentUniformAngle = angles[(currentIndex + 1) % angles.length];
    } else {
      this.currentUniformAngle = angles[(currentIndex - 1 + angles.length) % angles.length];
    }
  }

  getCurrentUniformImage(): string {
    if (!this.currentUniform) return '';
    return this.currentUniform.imageAngles[this.currentUniformAngle as keyof typeof this.currentUniform.imageAngles];
  }

  openUniformSelector(vehicleId: string, index: number): void {
    this.selectedUniformForVehicle = { vehicleId, index };
  }

  assignUniform(uniformId: string): void {
    if (!this.selectedUniformForVehicle) return;

    const selectedVehicle = this.selectedVehicles.find(
      sv => sv.vehicle.id === this.selectedUniformForVehicle!.vehicleId
    );

    if (selectedVehicle) {
      const assignment = selectedVehicle.uniformAssignments.find(
        ua => ua.vehicleIndex === this.selectedUniformForVehicle!.index
      );

      if (assignment) {
        assignment.uniformId = uniformId;
      }
    }

    this.selectedUniformForVehicle = null;
  }

  getUniformNameById(uniformId: string): string {
    const uniform = this.uniforms.find(u => u.id === uniformId);
    return uniform ? uniform.name : 'No asignado';
  }

  getUniformIcon(uniformId: string): string {
    const icons: { [key: string]: string } = {
      'camuflaje': '🎖️',
      'casual': '👔',
      'formal': '🤵'
    };
    return icons[uniformId] || '👤';
  }

  // MÉTODOS DE EQUIPAMIENTO
  toggleEquipment(equipment: Equipment): void {
    const index = this.selectedEquipment.findIndex(e => e.id === equipment.id);
    
    if (index > -1) {
      this.selectedEquipment.splice(index, 1);
    } else {
      this.selectedEquipment.push(equipment);
    }
  }

  isEquipmentSelected(equipmentId: string): boolean {
    return this.selectedEquipment.some(e => e.id === equipmentId);
  }

  // MÉTODOS DE NAVEGACIÓN
  requestCustomQuote(): void {
    this.router.navigate(['/contacto'], {
      queryParams: {
        tipo: 'cotizacion',
        servicio: 'proteccion-ejecutiva'
      }
    });
  }

  navigateTo(route: string): void {
    this.router.navigate([route]);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  scrollToSection(sectionId: string): void {
    const element = document.getElementById(sectionId);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  }
}
